const setProcurementRfqPublicationCommandPublicationID = `-- name: SetProcurementRfqPublicationCommandPublicationID :exec
UPDATE procurement_rfq_publication_commands
   SET publication_id = $2, updated_at = now()
 WHERE id = $1 AND publication_id IS NULL
`

type SetProcurementRfqPublicationCommandPublicationIDParams struct {
	ID            int64  `db:"id" json:"id"`
	PublicationID *int64 `db:"publication_id" json:"publication_id"`
}

// execute 成功後把 command 指回它建出來的 publication（Scope 6 步驟 4 之後的回放錨點；
// 見 schema 該欄的註解：失敗或仍在執行時為 NULL）。
//
// `publication_id IS NULL` 這個 guard 讓重複呼叫在一個已經有值的 command 上安全地變成
// no-op，同 SetProcurementAgentRunConversationID 的既有寫法——這是純粹的 metadata 回填，
// 不是狀態轉移，不碰任何 version，也不需要 CAS：真正的 exactly-one 保證是
// uq_procurement_rfq_publications_command 那條唯一索引。
func (q *Queries) SetProcurementRfqPublicationCommandPublicationID(ctx context.Context, arg SetProcurementRfqPublicationCommandPublicationIDParams) error {
	_, err := q.db.Exec(ctx, setProcurementRfqPublicationCommandPublicationID, arg.ID, arg.PublicationID)
	return err
}
